cd /home/user/rork-app && TOKEN=$(cat /tmp/owner_token.txt) && echo "=== 3. ALL 7 PROVIDERS RIGHT NOW ===" && for provider in github render supabase aws ai security storage; do
  curl -sS --max-time 30 -X POST "https://api.ivxholding.com/api/ivx/owner-variables/test" -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" -d "{\"provider\":\"$provider\"}" 2>/dev/null | bun -e "
